public class JSTypeRegistry_canPropertyBeDefined_TriageGen1Test {

    private JSTypeRegistry registry;
    private ErrorReporter errorReporter;

    @Before
    public void setUp() {
        errorReporter = mock(ErrorReporter.class);
        registry = new JSTypeRegistry(errorReporter);
    }

    /**
     * Tests the case where the property name does not exist in the registry at all.
     * Covers: if (typesIndexedByProperty.containsKey(propertyName)) -> false
     */
    @Test
    public void testCanPropertyBeDefined_PropertyDoesNotExist() {
        JSType type = mock(JSType.class);
        assertFalse(registry.canPropertyBeDefined(type, "nonExistentProperty"));
    }

    /**
     * Tests the case where the property exists, but the type provided is not a subtype
     * of any type that has that property (resulting in an empty type).
     * Covers: for loop iteration and if (!greatestSubtype.isEmptyType()) -> false
     */
    @Test
    public void testCanPropertyBeDefined_PropertyExistsButTypeIsMismatch() {
        String propName = "myProp";
        JSType typeWithProp = mock(JSType.class);
        JSType unionType = mock(JSType.class);

        // Mocking the union/alternate structure
        // Note: In Rhino, typesIndexedByProperty stores a type that might be a UnionType
        // We use registerPropertyOnType to populate the internal map
        registry.registerPropertyOnType(propName, typeWithProp);

        // The type we are checking against
        JSType inputType = mock(JSType.class);

        // Mock getGreatestSubtype to return an "empty" type (representing no overlap)
        JSType emptyType = mock(JSType.class);
        when(emptyType.isEmptyType()).thenReturn(true);
        when(typeWithProp.getGreatestSubtype(inputType)).thenReturn(emptyType);

        assertFalse(registry.canPropertyBeDefined(inputType, propName));
    }

    /**
     * Tests the successful case where the property exists and the input type 
     * is a valid subtype of a type containing that property.
     * Covers: if (!greatestSubtype.isEmptyType()) -> true
     */
    @Test
    public void testCanPropertyBeDefined_Success() {
        String propName = "validProp";
        JSType typeWithProp = mock(JSType.class);
        JSType validSubtype = mock(JSType.class);
        JSType inputType = mock(JSType.class);

        // Setup the registry with the property
        registry.registerPropertyOnType(propName, typeWithProp);

        // Mocking the behavior: 
        // typeWithProp.getGreatestSubtype(inputType) returns a non-empty type
        when(typeWithProp.getGreatestSubtype(inputType)).thenReturn(validSubtype);
        when(validSubtype.isEmptyType()).thenReturn(false);

        assertTrue(registry.canPropertyBeDefined(inputType, propName));
    }

    /**
     * Tests the case where the property exists and has multiple alternates (UnionType),
     * and the property is found in one of the alternates.
     * Covers: Iterating through the Alternates in the loop.
     */
    @Test
    public void testCanPropertyBeDefined_WithMultipleAlternates() {
        String propName = "unionProp";
        JSType unionType = mock(JSType.class);
        JSType alt1 = mock(JSType.class);
        JSType alt2 = mock(JSType.class);
        JSType inputType = mock(JSType.class);

        // Mocking the union/alternates structure
        // In Rhino, JSType.getAlternates() is used for UnionTypes
        when(unionType.getAlternates()).thenReturn(java.util.Arrays.asList(alt1, alt2));

        // Mock alt1 to be a mismatch (empty)
        JSType emptyType = mock(JSType.class);
        when(emptyType.isEmptyType()).thenReturn(true);
        when(alt1.getGreatestSubtype(inputType)).thenReturn(emptyType);

        // Mock alt2 to be a match (not empty)
        JSType validSubtype = mock(JSType.class);
        when(validSubtype.isEmptyType()).thenReturn(false);
        when(alt2.getGreatestSubtype(inputType)).thenReturn(validSubtype);

        registry.registerPropertyOnType(propName, unionType);

        assertTrue(registry.canPropertyBeDefined(inputType, propName));
    }
}
